"use client"

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"

// Leather Luxe RadioGroup: recessed circular wells; the selected indicator
// is a cognac leather dot with the Button's sheen and rim, scaled down.

function RadioGroup({ className, ...props }: RadioGroupPrimitive.Props) {
  return (
    <RadioGroupPrimitive data-slot="radio-group" className={cn("grid gap-2.5", className)} {...props} />
  )
}
RadioGroup.displayName = "RadioGroup"

function RadioGroupItem({ className, ...props }: RadioPrimitive.Root.Props) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square h-5 w-5 rounded-full",
        "border border-border bg-well [box-shadow:var(--shadow-well)]",
        "transition-[border-color,box-shadow] duration-base",
        "hover:border-highlight",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        className
      )}
      {...props}
    >
      <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full flex items-center justify-center">
        <span
          className={cn(
            "relative block h-3 w-3 rounded-full",
            "[background-image:var(--gradient-leather)]",
            "border border-[oklch(0.68_0.115_58/0.55)]",
            "[box-shadow:var(--shadow-leather-sm)]"
          )}
        />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  )
}
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
